#!/bin/sh
# I434: a SID file plays through `selecta-cli render` as a RENDER-kind replayer (sid, libsidplayfp). One reachability
# test through the product entry point; the sentinel is the `replayer=sid` line of render. Fixture:
# tests/m3/fixtures/sid_test.sid (generated by make_sid_fixture.py, endless tone, source in sid_test.sid.SOURCE).
# Asserts: the plugin ran, the WAV is not silent (energy of the 16-bit samples) and the rendered frame count equals
# 10 s +-1% at the output rate. Needs SELECTA_PLUGIN_PATH to hold the sid module (set by the test registration).
# usage: sid_decode.sh <selecta-cli> <sid-file>
set -u
cli=$1
sid=$2
field() { printf '%s\n' "$1" | tr ' ' '\n' | sed -n "s/^$2=//p" | head -1; }
fail() { echo "FAIL: $*"; exit 1; }
rate=44100
rm -f fd_sid.wav
out=$("$cli" render "$sid" --output fd_sid.wav --seconds 10 --rate "$rate" 2>/dev/null) || fail "render failed"
[ "$(field "$out" replayer)" = "sid" ] || fail "replayer=$(field "$out" replayer), want sid"
got=$(field "$out" rendered_frames)
awk -v g="$got" -v w=$((rate * 10)) 'BEGIN { d = g - w; if (d < 0) d = -d; exit !(d <= w * 0.01) }' ||
    fail "rendered_frames=$got, want $((rate * 10)) +-1%"
e=$(od -An -v -t d2 -j 44 fd_sid.wav | tr -s " " "\n" | awk '$1 != "" { s += $1 * $1 } END { printf "%d", s }')
[ "$e" -gt 1000000 ] || fail "silent output (energy $e)"
echo sid_decode_ok
